    static long mod = 998244353;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        long n = sc.nextInt();
        long m = sc.nextInt();
        long L = sc.nextInt();
        long R = sc.nextInt();
        if (n % 2 == 1 && m % 2 == 1) {
            System.out.println(pow((R - L + 1) % mod, n * m));
        } else {
            long cnt = R - L + 1;
            if (cnt % 2 == 0) {
                long allbutone = pow(cnt % mod, n * m - 1);
                System.out.println(allbutone * (cnt / 2) % mod);
            } else {
                long k = cnt / 2;
                long[][] mat = { { k, k + 1 }, { k + 1, k } };
                long[][] res = matPow(mat, n * m);
                System.out.println(res[0][0]);
            }
        }
    }

    static long[][] matMul(long[][] a, long[][] b) {
        long[][] c = new long[2][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
