        return c;
    }

    static long[][] matPow(long[][] a, long e) {
        long[][] res = { { 1, 0 }, { 0, 1 } };
        long[][] base = new long[2][2];
        for (int i = 0; i < 2; i++) {
            base[i] = a[i].clone();
